import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import {
  customerInput, bikeInput, itemInput, jobInput, expenseInput, date, id, money, totals, garageDate, serviceStage,
  type Kind, type Records, type Job, type Invoice, type Payment, type Report,
} from '@garage/shared';
import type { Pool, PoolClient } from 'pg';
import { get, save, transaction, audit, settings } from './db.js';

export class DomainError extends Error {
  /** Describe a recoverable business validation error with an HTTP status. */
  constructor(message: string, public statusCode = 400) { super(message); }
}

/** Require an existing referenced record, returning a clear 404 otherwise. */
export async function required<K extends Kind>(db: PoolClient | Pool, kind: K, recordId: string): Promise<Records[K]> {
  const value = await get(db, kind, recordId);
  if (!value) throw new DomainError(`${kind} record not found`, 404);
  return value;
}

/** Create or update a customer and record explicit WhatsApp consent timing. */
export async function customer(db: PoolClient, input: unknown, recordId: string = randomUUID()) {
  const value = customerInput.parse(input);
  const old = await get(db, 'customers', recordId);
  return save(db, 'customers', {
    ...value, id: recordId, consentAt: value.whatsappConsent ? old?.consentAt || new Date().toISOString() : null,
  });
}

/** Register a bike against an existing customer, preventing duplicate registration numbers. */
export async function bike(db: PoolClient, input: unknown) {
  const value = bikeInput.parse(input);
  await required(db, 'customers', value.customerId);
  const duplicate = await db.query("SELECT id FROM records WHERE kind='bikes' AND data->>'registration'=$1", [value.registration]);
  if (duplicate.rowCount) throw new DomainError('Bike registration already exists', 409);
  return save(db, 'bikes', { ...value, id: randomUUID() });
}

/** Create an inventory item and its auditable opening stock movement. */
export async function item(db: PoolClient, input: unknown, actorId: string) {
  const value = itemInput.parse(input);
  const duplicate = await db.query("SELECT id FROM records WHERE kind='items' AND LOWER(data->>'sku')=LOWER($1)", [value.sku]);
  if (duplicate.rowCount) throw new DomainError('SKU already exists', 409);
  const created = await save(db, 'items', { ...value, id: randomUUID() });
  await save(db, 'movements', {
    id: randomUUID(), itemId: created.id, delta: value.quantity, reason: 'Opening stock',
    date: new Date().toISOString(), actorId,
  });
  return created;
}

/** Adjust stock without allowing negative inventory; every adjustment has a reason. */
export async function adjustStock(db: PoolClient, itemId: string, input: unknown, actorId: string) {
  const value = z.object({
    delta: z.number().int().min(-1_000_000).max(1_000_000).refine(v => v !== 0),
    reason: z.string().trim().min(1).max(200),
  }).strict().parse(input);
  const current = await required(db, 'items', itemId);
  const quantity = current.quantity + value.delta;
  if (quantity < 0 || quantity > 1_000_000) throw new DomainError('Stock adjustment is outside allowed quantity');
  await save(db, 'movements', { id: randomUUID(), itemId, ...value, date: new Date().toISOString(), actorId });
  return save(db, 'items', { ...current, quantity });
}

/** Open a priced job card; parts are consumed only when the service completes. */
export async function createJob(db: PoolClient, input: unknown, actorId: string, existing?: Job) {
  const value = jobInput.parse(input);
  const vehicle = await required(db, 'bikes', value.bikeId);
  const client = await required(db, 'customers', vehicle.customerId);
  if (value.odometer < vehicle.odometer) throw new DomainError('Odometer cannot decrease');
  if (value.nextServiceDate && value.nextServiceDate <= value.serviceDate) throw new DomainError('Next service must be after service date');
  if (value.promisedDelivery && garageDate(new Date(value.promisedDelivery)) < value.serviceDate) throw new DomainError('Promised delivery cannot be before the service date');
  if (value.assignedTo) {
    const staff = await db.query('SELECT id FROM users WHERE id=$1 AND active=TRUE', [value.assignedTo]);
    if (!staff.rowCount) throw new DomainError('Assigned staff member is not active');
  }
  if (new Set(value.parts.map(part => part.itemId)).size !== value.parts.length) throw new DomainError('Combine repeated parts into one line');
  const parts = [];
  for (const line of value.parts) {
    const stock = await required(db, 'items', line.itemId);
    parts.push({ ...line, sku: stock.sku, name: stock.name, pricePaise: stock.pricePaise });
  }
  totals(parts, value.laborPaise, value.gstBasisPoints);
  if (existing) {
    if (existing.status === 'completed' || existing.status === 'cancelled') throw new DomainError('Closed service lines cannot be edited', 409);
    if (value.bikeId !== existing.bikeId) throw new DomainError('A service cannot be moved to another bike');
    if ((existing.timeline?.length || 0) >= 198) throw new DomainError('Service note limit reached; remaining events are reserved for completion and delivery');
    return save(db, 'jobs', {
      ...existing, ...value, parts, assignedTo: value.assignedTo, nextServiceDate: value.nextServiceDate,
      promisedDelivery: value.promisedDelivery,
      timeline: [...(existing.timeline || []), {
        id: randomUUID(), stage: existing.stage || 'received', note: 'Service work lines / estimate updated. Obtain customer approval for revised charges.',
        at: new Date().toISOString(), actorId,
      }],
    });
  }
  return save(db, 'jobs', {
    ...value, parts, id: randomUUID(), registration: vehicle.registration, customerName: client.name, status: 'open', stage: 'received',
    timeline: [{ id: randomUUID(), stage: 'received', note: 'Bike service registered', at: new Date().toISOString(), actorId }],
  });
}

/** Record owner-managed customer-visible progress; delivery requires a completed, invoiced service. */
export async function trackJob(db: PoolClient, jobId: string, input: unknown, actorId: string) {
  const value = z.object({
    stage: serviceStage, note: z.string().trim().min(1).max(2000),
    promisedDelivery: z.string().datetime({ offset: true }).optional(),
  }).strict().parse(input);
  const job = await required(db, 'jobs', jobId);
  if (value.promisedDelivery && garageDate(new Date(value.promisedDelivery)) < job.serviceDate) throw new DomainError('Promised delivery cannot be before the service date');
  if (job.status === 'cancelled' || job.stage === 'delivered') throw new DomainError('Cancelled or delivered service tracking is closed', 409);
  if (value.stage === 'cancelled') throw new DomainError('Use Cancel job to cancel the service');
  if (job.status === 'completed' && !['ready', 'delivered'].includes(value.stage)) throw new DomainError('Completed service can only be ready or delivered', 409);
  if (['ready', 'delivered'].includes(value.stage) && job.status !== 'completed') throw new DomainError('Complete and invoice the service before marking ready or delivered', 409);
  const eventLimit = value.stage === 'delivered' ? 200 : job.status === 'completed' ? 199 : 198;
  if ((job.timeline?.length || 0) >= eventLimit) throw new DomainError('Service note limit reached; remaining events are reserved for completion and delivery');
  const event = { id: randomUUID(), ...value, at: new Date().toISOString(), actorId };
  return save(db, 'jobs', {
    ...job, stage: value.stage, promisedDelivery: value.promisedDelivery || job.promisedDelivery,
    timeline: [...(job.timeline || []), { id: event.id, stage: event.stage, note: event.note, at: event.at, actorId }],
  });
}

/** Queue an immutable timeline event for consent-based WhatsApp sharing with safe request retries. */
export async function queueStatus(db: PoolClient, jobId: string, input: unknown) {
  const { eventId } = z.object({ eventId: id }).strict().parse(input);
  const job = await required(db, 'jobs', jobId);
  const event = job.timeline?.find(value => value.id === eventId);
  if (!event) throw new DomainError('Service timeline event not found', 404);
  if (job.timeline?.[job.timeline.length - 1]?.id !== eventId) throw new DomainError('Share the latest service event, not an obsolete update', 409);
  const vehicle = await required(db, 'bikes', job.bikeId);
  const client = await required(db, 'customers', vehicle.customerId);
  if (!client.whatsappConsent) throw new DomainError('Customer has not consented to WhatsApp service updates', 409);
  const prior = await get(db, 'reminders', eventId);
  if (prior) {
    if (prior.jobId !== jobId || prior.purpose !== 'service_status') throw new DomainError('Status message key is already in use', 409);
    return prior;
  }
  return save(db, 'reminders', {
    id: eventId, eventId, jobId, purpose: 'service_status', stage: event.stage, note: event.note,
    promisedDelivery: job.promisedDelivery, dueDate: garageDate(), status: 'pending',
    attempts: 0, nextAttempt: new Date().toISOString(), error: null, sentAt: null,
  });
}

/** Transition a job atomically, consuming stock and creating exactly one invoice and reminder on completion. */
export async function transitionJob(db: PoolClient, jobId: string, input: unknown, actorId: string) {
  const { status } = z.object({ status: z.enum(['in_progress', 'completed', 'cancelled']) }).strict().parse(input);
  const job = await required(db, 'jobs', jobId);
  if (job.status === 'completed' || job.status === 'cancelled') throw new DomainError('Closed job cannot be changed', 409);
  if (job.status === status) throw new DomainError('Job already has this status', 409);
  if ((job.timeline?.length || 0) >= (status === 'in_progress' ? 198 : 199)) throw new DomainError('Service timeline limit reached');
  if (status === 'completed') {
    const vehicle = await required(db, 'bikes', job.bikeId);
    const client = await required(db, 'customers', vehicle.customerId);
    const stocks = [];
    for (const part of job.parts) {
      const stock = await required(db, 'items', part.itemId);
      if (stock.quantity < part.quantity) throw new DomainError(`Insufficient stock: ${stock.name}`, 409);
      stocks.push({ stock, part });
    }
    const garage = await settings(db);
    if (job.gstBasisPoints > 0 && !garage.gstin) throw new DomainError('Configure a valid garage GSTIN before issuing GST invoices');
    const calculated = totals(job.parts, job.laborPaise, job.gstBasisPoints);
    const sequence = await db.query<{ invoice_sequence: number }>('UPDATE garage SET invoice_sequence=invoice_sequence+1 WHERE id=1 RETURNING invoice_sequence');
    for (const { stock, part } of stocks) {
      await save(db, 'items', { ...stock, quantity: stock.quantity - part.quantity });
      await save(db, 'movements', {
        id: randomUUID(), itemId: stock.id, delta: -part.quantity, reason: `Service ${job.id}`,
        date: new Date().toISOString(), actorId,
      });
    }
    const invoice: Invoice = {
      id: randomUUID(), number: `GM-${String(sequence.rows[0].invoice_sequence).padStart(6, '0')}`,
      jobId, customerId: client.id, customerName: client.name, phone: client.phone,
      registration: vehicle.registration, garage, date: job.serviceDate,
      parts: job.parts, laborPaise: job.laborPaise, gstBasisPoints: job.gstBasisPoints, ...calculated,
    };
    await save(db, 'invoices', invoice);
    await save(db, 'bikes', { ...vehicle, odometer: Math.max(vehicle.odometer, job.odometer) });
    if (job.nextServiceDate) {
      await save(db, 'reminders', {
        id: randomUUID(), jobId, dueDate: job.nextServiceDate, status: 'pending', attempts: 0,
        nextAttempt: new Date().toISOString(), error: null, sentAt: null,
      });
    }
  }
  const stage = status === 'completed' ? 'ready' : status === 'cancelled' ? 'cancelled' : 'working';
  return save(db, 'jobs', { ...job, status, stage, timeline: [...(job.timeline || []), {
    id: randomUUID(), stage, note: status === 'completed' ? 'Service completed, invoice created, bike ready for collection' : `Service ${status.replace('_', ' ')}`,
    at: new Date().toISOString(), actorId,
  }] });
}

/** Record a payment under the garage lock so concurrent payments cannot overpay an invoice. */
export async function payment(db: PoolClient, invoiceId: string, input: unknown) {
  const value = z.object({
    amountPaise: money.refine(v => v > 0), method: z.enum(['cash', 'upi', 'card', 'bank']),
    date, reference: z.string().trim().max(200).default(''), idempotencyKey: id,
  }).strict().parse(input);
  const existing = await get(db, 'payments', value.idempotencyKey);
  if (existing) {
    if (existing.invoiceId !== invoiceId || existing.amountPaise !== value.amountPaise ||
        existing.method !== value.method || existing.date !== value.date || existing.reference !== value.reference) {
      throw new DomainError('Payment request key was already used for a different payment', 409);
    }
    return existing;
  }
  const invoice = await required(db, 'invoices', invoiceId);
  const paid = await db.query<{ data: Payment }>("SELECT data FROM records WHERE kind='payments' AND data->>'invoiceId'=$1", [invoiceId]);
  const totalPaid = paid.rows.reduce((sum, row) => sum + row.data.amountPaise, 0);
  if (totalPaid + value.amountPaise > invoice.totalPaise) throw new DomainError('Payment exceeds outstanding balance', 409);
  const { idempotencyKey, ...fields } = value;
  return save(db, 'payments', { ...fields, id: idempotencyKey, invoiceId });
}

/** Add an expense with a positive amount and validated accounting date. */
export async function expense(db: PoolClient, input: unknown) {
  return save(db, 'expenses', { ...expenseInput.parse(input), id: randomUUID() });
}

/** Return accounting totals without exposing financial reports to mechanic accounts. */
export async function report(pool: Pool, from: string, to: string): Promise<Report> {
  const rows = await pool.query<{ kind: Kind; data: Records[Kind] }>(
    "SELECT kind,data FROM records WHERE kind IN ('invoices','payments','expenses','jobs','items','reminders')",
  );
  let invoiceTotalPaise = 0, receivedPaise = 0, expensePaise = 0, allInvoiced = 0, allPaid = 0;
  let openJobs = 0, lowStock = 0, dueServices = 0;
  const today = garageDate();
  for (const row of rows.rows) {
    if (row.kind === 'invoices') {
      const value = row.data as Invoice;
      allInvoiced += value.totalPaise;
      if (value.date >= from && value.date <= to) invoiceTotalPaise += value.totalPaise;
    } else if (row.kind === 'payments') {
      const value = row.data as Payment;
      allPaid += value.amountPaise;
      if (value.date >= from && value.date <= to) receivedPaise += value.amountPaise;
    } else if (row.kind === 'expenses') {
      const value = row.data as Records['expenses'];
      if (value.date >= from && value.date <= to) expensePaise += value.amountPaise;
    } else if (row.kind === 'jobs') {
      if (['open', 'in_progress'].includes((row.data as Job).status)) openJobs++;
    } else if (row.kind === 'items') {
      const value = row.data as Records['items'];
      if (value.quantity <= value.reorderLevel) lowStock++;
    } else {
      const value = row.data as Records['reminders'];
      if (value.purpose !== 'service_status' && value.dueDate <= today && !['sent', 'skipped'].includes(value.status)) dueServices++;
    }
  }
  return { invoiceTotalPaise, receivedPaise, expensePaise, outstandingPaise: allInvoiced - allPaid,
    cashNetPaise: receivedPaise - expensePaise, openJobs, lowStock, dueServices };
}

/** Apply a mutation and write its audit action in the same transaction. */
export async function mutate<T>(pool: Pool, actorId: string, action: string, run: (db: PoolClient) => Promise<T>) {
  return transaction(pool, async db => {
    const result = await run(db);
    await audit(db, actorId, action);
    return result;
  });
}
